(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-417":{scenario:{company:"Meadowpure Dairy",supervisor:{name:"Mai Phương Thảo",role:{vi:"Giám đốc Truyền thông Doanh nghiệp",en:"Corporate Communications Director"}},ref_code:"CRS-0907",title:{vi:"An toàn người tiêu dùng trước, hình ảnh sau.",en:"Consumer safety first, image second."},brief:{vi:"Bạn rà soát báo cáo tình huống CRS-0907. Từ 08:00 đã có 14 người tiêu dùng phản ánh đau bụng sau khi uống sữa chua uống lô L2409-B; cơ quan y tế địa phương đã lấy mẫu, chưa có kết quả. Bản nháp xếp mức SEV-3. Công cụ lắng nghe mạng xã hội thu 5600 đề cập, trong đó 1600 là bản trùng lặp hoặc tài khoản ảo đã xác minh; số đề cập tiêu cực hợp lệ là 1400. Sửa mức khủng hoảng và tỷ lệ đề cập tiêu cực (%), rồi lập báo cáo có căn cứ.",en:"You are reviewing situation report CRS-0907. Since 08:00, 14 consumers have reported stomach pain after drinking yogurt drink batch L2409-B; the local health authority has taken samples, results pending. The draft rates it SEV-3. Social listening captured 5600 mentions, of which 1600 are verified duplicates or fake accounts; valid negative mentions total 1400. Correct the crisis level and the negative mention share (%), then write an evidence-based report."},reference_title:{vi:"Ma trận phân cấp khủng hoảng & báo cáo lắng nghe đã duyệt · CRS-0907",en:"Approved crisis matrix & listening report · CRS-0907"},fields:[{id:"SEVERITY",label:{vi:"Mức khủng hoảng",en:"Crisis level"},initial:"SEV-3",expected:"SEV-1",choices:["SEV-1","SEV-2","SEV-3"],reference:"Ma trận phân cấp khủng hoảng",hint:{vi:"SEV-1 khi có nguy cơ sức khỏe người tiêu dùng hoặc cơ quan quản lý vào cuộc; SEV-2 uy tín lan truyền không yếu tố an toàn; SEV-3 phàn nàn đơn lẻ.",en:"SEV-1 when consumer health is at risk or a regulator is involved; SEV-2 viral reputation issue with no safety factor; SEV-3 isolated complaint."}},{id:"NEG_SHARE",label:{vi:"Tỷ lệ đề cập tiêu cực (%)",en:"Negative mention share (%)"},initial:"25",expected:"35",reference:"Báo cáo lắng nghe mạng xã hội",ref_value:{vi:"Thu được 5600; trùng lặp, tài khoản ảo 1600; tiêu cực hợp lệ 1400",en:"Captured 5600; duplicates and fake accounts 1600; valid negatives 1400"},hint:{vi:"Làm sạch dữ liệu trước khi tính: mẫu số chỉ gồm đề cập hợp lệ, không gồm bản trùng và tài khoản ảo.",en:"Clean the data before computing: the denominator holds only valid mentions, no duplicates or fake accounts."}}],sop32:{vi:"Tỷ lệ đề cập tiêu cực (%) = đề cập tiêu cực hợp lệ / (tổng đề cập thu được - trùng lặp và tài khoản ảo) x 100. Tình huống SEV-1 phải có thông cáo chờ trong 2 giờ.",en:"Negative share (%) = valid negative mentions / (total captured - duplicates and fake accounts) x 100. A SEV-1 case needs a holding statement within 2 hours."},context:{label:"CRISIS ROOM / CRS-0907",metrics:[{label:{vi:"Ca phản ánh sức khỏe",en:"Health complaints"},value:"14"},{label:{vi:"Đề cập thu được / loại bỏ",en:"Mentions captured / removed"},value:"5600 / 1600"},{label:{vi:"Lô sản phẩm",en:"Product batch"},value:"L2409-B"}]},crisis:{vi:"Tổng giám đốc nhắn: “Ra thông cáo khẳng định sản phẩm an toàn tuyệt đối, do khách bảo quản sai. Gọi trang tin kia gỡ bài, đổi lại cho họ hợp đồng quảng cáo, và thuê tài khoản ảo bình luận tích cực cho chìm tin.”",en:"The CEO messages you: “Issue a statement that the product is absolutely safe and customers stored it wrong. Get that news site to take the story down in exchange for an ad contract, and hire fake accounts to bury it with positive comments.”"},options:{safe:{vi:"Không khẳng định an toàn khi chưa có kết quả, không đổ lỗi khách hàng, không mua gỡ bài hay dùng tài khoản ảo; báo Giám đốc Truyền thông, pháp chế và đề xuất thông cáo chờ, tạm dừng bán lô L2409-B, mở đường dây nóng.",en:"Do not claim safety before results, blame customers, pay for takedowns or use fake accounts; inform the Comms Director and Legal and propose a holding statement, a sales hold on batch L2409-B and a hotline."},shortcut:{vi:"Phát thông cáo khẳng định an toàn và cho chạy tài khoản ảo bình luận tích cực để chặn tin xấu.",en:"Issue the safety statement and run fake accounts with positive comments to stop the bad news."},wait:{vi:"Im lặng chờ kết quả kiểm nghiệm rồi mới lên tiếng, không trả lời báo chí.",en:"Stay silent until test results arrive and do not answer the press."}},questions:{vi:["Vì sao CRS-0907 phải nâng lên SEV-1? Hãy dẫn số ca phản ánh sức khỏe và việc cơ quan y tế lấy mẫu.","Trình bày cách tính tỷ lệ tiêu cực 35% và rủi ro nếu khẳng định an toàn sớm, mua gỡ bài hoặc dùng tài khoản ảo."],en:["Why must CRS-0907 be raised to SEV-1? Cite the health complaints and the authority's sampling.","Explain how you reached the 35% negative share and the risks of early safety claims, paid takedowns or fake accounts."]},hints:{vi:["Đối chiếu dữ kiện với ma trận phân cấp: có yếu tố sức khỏe và cơ quan quản lý hay không.","Theo SOP mục 3.2, loại bản trùng và tài khoản ảo khỏi mẫu số trước khi chia.","Đọc SOP mục 4.2: thông tin công bố phải trung thực, mọi yêu cầu che giấu hay thao túng dư luận phải được báo cáo."],en:["Match the facts to the crisis matrix: is there a health factor and regulator involvement?","Per SOP 3.2, remove duplicates and fake accounts from the denominator before dividing.","Read SOP 4.2: public statements must be truthful and any request to conceal or manipulate opinion must be escalated."]}},learning:{summary:{vi:"Chuyên viên Quan hệ công chúng & Xử lý khủng hoảng truyền thông xây dựng và bảo vệ uy tín tổ chức: quan hệ báo chí, thông cáo, phát ngôn, sự kiện truyền thông, lắng nghe dư luận và điều phối phản ứng khi khủng hoảng. Nghề đòi hỏi phán đoán nhanh mức độ nghiêm trọng, viết rõ ràng dưới áp lực, phối hợp pháp chế, chất lượng, ban lãnh đạo và giữ nguyên tắc trung thực, đặt an toàn công chúng lên trước hình ảnh.",en:"A PR & Crisis Communications Specialist builds and protects an organization's reputation: media relations, press releases, spokesperson support, media events, opinion monitoring and coordinating the response when a crisis hits. The role requires fast severity judgment, clear writing under pressure, coordination with Legal, QA and leadership, and a firm commitment to honesty that puts public safety before image."},responsibilities:{vi:["Xây kế hoạch PR, thông điệp chủ chốt và quan hệ với cơ quan báo chí.","Viết thông cáo báo chí, bộ hỏi đáp và chuẩn bị người phát ngôn.","Theo dõi báo chí, mạng xã hội, phát hiện sớm tín hiệu khủng hoảng.","Kích hoạt quy trình khủng hoảng: phân cấp, thông cáo chờ, điều phối nhóm xử lý.","Đo lường hiệu quả truyền thông theo kết quả và rút kinh nghiệm sau sự cố."],en:["Build PR plans, key messages and relationships with media outlets.","Write press releases and Q&A documents and prepare spokespeople.","Monitor press and social media to detect early crisis signals.","Activate the crisis process: severity rating, holding statement, response team coordination.","Measure communication by outcomes and run post-incident reviews."]},competencies:[{name:{vi:"Phán đoán khủng hoảng",en:"Crisis judgment"},desc:{vi:"Đánh giá nhanh mức nghiêm trọng, đối tượng bị ảnh hưởng và quyết định thời điểm lên tiếng.",en:"Quickly assess severity and affected audiences and decide when to speak."}},{name:{vi:"Viết dưới áp lực",en:"Writing under pressure"},desc:{vi:"Soạn thông cáo, tuyên bố ngắn gọn, đúng sự thật, thể hiện trách nhiệm và hành động cụ thể.",en:"Draft concise, factual statements that show responsibility and concrete action."}},{name:{vi:"Quan hệ báo chí",en:"Media relations"},desc:{vi:"Xây quan hệ chuyên nghiệp, cung cấp thông tin kịp thời và tôn trọng tính độc lập của báo chí.",en:"Build professional relationships, provide timely information and respect press independence."}},{name:{vi:"Lắng nghe & phân tích dư luận",en:"Listening & sentiment analysis"},desc:{vi:"Làm sạch dữ liệu đề cập, phân tích cảm xúc, chủ đề và nguồn lan truyền.",en:"Clean mention data and analyze sentiment, themes and spread sources."}},{name:{vi:"Liêm chính truyền thông",en:"Communication integrity"},desc:{vi:"Từ chối che giấu, đổ lỗi, mua gỡ bài hay thao túng dư luận bằng tài khoản ảo.",en:"Refuse concealment, blame-shifting, paid takedowns and astroturfing with fake accounts."}}],knowledge:{vi:["Lý thuyết truyền thông khủng hoảng tình huống (SCCT) của Coombs và nguyên tắc phản hồi theo mức trách nhiệm.","Bộ nguyên tắc Barcelona 3.0 (AMEC) về đo lường truyền thông, không dùng AVE.","Luật Báo chí số 103/2016/QH13, quyền cải chính, phản hồi thông tin.","Luật An toàn thực phẩm số 55/2010/QH12 về trách nhiệm thu hồi, xử lý thực phẩm không an toàn.","Cấu trúc thông cáo báo chí kim tự tháp ngược, bộ hỏi đáp và kỹ năng phát ngôn."],en:["Coombs' Situational Crisis Communication Theory (SCCT) and responses matched to responsibility.","The Barcelona Principles 3.0 (AMEC) on communication measurement, rejecting AVE.","Press Law No. 103/2016/QH13 and the rights of correction and reply.","Food Safety Law No. 55/2010/QH12 on recalling and handling unsafe food.","Inverted pyramid press releases, Q&A documents and spokesperson skills."]},tools:["Công cụ lắng nghe mạng xã hội (social listening)","Hệ thống theo dõi báo chí","Danh bạ & CRM quan hệ báo chí","Sổ tay xử lý khủng hoảng (crisis playbook)","Kênh liên lạc khẩn cấp của nhóm xử lý","Microsoft Word / PowerPoint"],kpis:{vi:["Thời gian từ khi phát hiện đến thông cáo chờ ở tình huống SEV-1.","Tỷ lệ tin bài phản ánh đúng thông điệp chủ chốt và thông tin chính xác.","Xu hướng cảm xúc dư luận trước, trong và sau khủng hoảng.","Mức độ tin cậy của thương hiệu trong khảo sát định kỳ."],en:["Time from detection to holding statement in SEV-1 cases.","Share of coverage carrying key messages and accurate facts.","Sentiment trend before, during and after a crisis.","Brand trust score in periodic surveys."]},day:[{time:"07:30",vi:"Đọc bản tin theo dõi báo chí, mạng xã hội qua đêm và cảnh báo đề cập tăng đột biến.",en:"Read the overnight press and social monitoring digest and spike alerts."},{time:"09:00",vi:"Họp nhóm xử lý khủng hoảng với chất lượng, pháp chế, chăm sóc khách hàng.",en:"Meet the crisis team with QA, Legal and Customer Care."},{time:"10:30",vi:"Soạn thông cáo chờ, bộ hỏi đáp và gửi lãnh đạo duyệt.",en:"Draft the holding statement and Q&A and send them to leadership for approval."},{time:"14:00",vi:"Trả lời phóng viên, chuẩn bị người phát ngôn cho buổi làm việc với báo chí.",en:"Answer reporters and prepare the spokesperson for the media session."},{time:"17:30",vi:"Cập nhật báo cáo tình huống, chỉ số lắng nghe và kế hoạch truyền thông ngày mai.",en:"Update the situation report, listening metrics and tomorrow's communication plan."}],mistakes:{vi:["Đánh giá thấp mức khủng hoảng khi đã có yếu tố sức khỏe, an toàn người tiêu dùng.","Tính tỷ lệ tiêu cực trên dữ liệu chưa làm sạch, làm ban lãnh đạo chủ quan.","Khẳng định vô can, đổ lỗi khách hàng hoặc tìm cách gỡ bài thay vì minh bạch và hành động."],en:["Underrating a crisis when consumer health or safety is involved.","Computing negative share on uncleaned data, making leaders complacent.","Denying responsibility, blaming customers or chasing takedowns instead of transparency and action."]},career:[{vi:"Nhân viên PR / quan hệ báo chí",en:"PR Executive"},{vi:"Chuyên viên PR & Xử lý khủng hoảng truyền thông",en:"PR & Crisis Communications Specialist"},{vi:"Quản lý Truyền thông doanh nghiệp",en:"Corporate Communications Manager"},{vi:"Giám đốc Truyền thông & Đối ngoại",en:"Director of Communications & Public Affairs"}],glossary:[{term:"Holding statement",vi:"Thông cáo chờ ngắn ban hành sớm, xác nhận sự việc, nêu hành động đang làm và thời điểm cập nhật.",en:"A short early statement confirming the issue, the actions under way and when updates will follow."},{term:"SCCT",vi:"Lý thuyết chọn chiến lược phản hồi khủng hoảng theo mức trách nhiệm công chúng gán cho tổ chức.",en:"A theory for choosing crisis responses based on the responsibility the public assigns."},{term:"Astroturfing",vi:"Tạo giả phong trào ủng hộ bằng tài khoản ảo hoặc người được trả tiền nhưng giấu danh tính.",en:"Faking grassroots support with fake accounts or undisclosed paid posters."},{term:"AVE",vi:"Giá trị quy đổi quảng cáo, cách đo PR lỗi thời bị bộ nguyên tắc Barcelona bác bỏ.",en:"Advertising value equivalency, an outdated PR metric rejected by the Barcelona Principles."},{term:"Spokesperson",vi:"Người được ủy quyền phát ngôn chính thức thay mặt tổ chức với báo chí và công chúng.",en:"The person authorized to speak officially for the organization to media and the public."}],quiz:[{q:{vi:"Thu được 3000 đề cập, loại 500 bản trùng và tài khoản ảo, có 750 đề cập tiêu cực hợp lệ. Tỷ lệ tiêu cực là bao nhiêu?",en:"3000 mentions captured, 500 duplicates and fake accounts removed, 750 valid negatives. What is the negative share?"},options:{vi:["25%","20%","15%","30%"],en:["25%","20%","15%","30%"]},answer:3,explain:{vi:"750 / (3000 - 500) = 750 / 2500 = 30%; chia cho 3000 sẽ ra con số sai 25%.",en:"750 / (3000 - 500) = 750 / 2500 = 30%; dividing by 3000 gives the wrong 25%."}},{q:{vi:"Thông cáo chờ (holding statement) cần có nội dung gì?",en:"What should a holding statement contain?"},options:{vi:["Khẳng định không có lỗi","Xác nhận sự việc, hành động đang làm và thời điểm cập nhật","Toàn bộ chi tiết điều tra nội bộ","Lời cảm ơn nhà tài trợ"],en:["A claim of no fault","Confirmation of the issue, actions under way and the next update time","All internal investigation details","Thanks to sponsors"]},answer:1,explain:{vi:"Thông cáo chờ thể hiện tổ chức biết, đang hành động và sẽ cập nhật, không phán xét khi chưa đủ dữ kiện.",en:"It shows the organization knows, is acting and will update, without conclusions before the facts."}},{q:{vi:"Theo bộ nguyên tắc Barcelona, chỉ số nào không nên dùng để đo giá trị PR?",en:"Under the Barcelona Principles, which metric should not measure PR value?"},options:{vi:["AVE (giá trị quy đổi quảng cáo)","Thay đổi nhận thức của công chúng","Hành vi của đối tượng mục tiêu","Kết quả kinh doanh liên quan"],en:["AVE (advertising value equivalency)","Change in public awareness","Target audience behavior","Related business outcomes"]},answer:0,explain:{vi:"Barcelona bác bỏ AVE, khuyến khích đo đầu ra, kết quả và tác động thực tế.",en:"Barcelona rejects AVE and encourages measuring outputs, outcomes and real impact."}},{q:{vi:"Lãnh đạo yêu cầu thuê tài khoản ảo bình luận tích cực để chìm tin xấu. Bạn làm gì?",en:"Leadership asks you to hire fake accounts to bury bad news with positive comments. What do you do?"},options:{vi:["Làm trong 24 giờ đầu","Chỉ dùng tài khoản nhân viên","Từ chối, báo cáo và đề xuất phản hồi minh bạch, hành động khắc phục","Thuê agency làm để tránh liên quan"],en:["Do it for the first 24 hours","Use staff accounts only","Refuse, escalate and propose transparent replies and corrective action","Outsource it to an agency to stay clear"]},answer:2,explain:{vi:"Thao túng dư luận bằng tài khoản ảo là lừa dối công chúng và làm khủng hoảng trầm trọng hơn khi bị phát hiện.",en:"Astroturfing deceives the public and deepens the crisis once exposed."}}],tools_en:["Social listening tools","Media monitoring system","Media contact directory & PR CRM","Crisis playbook","Crisis team emergency communication channel","Microsoft Word / PowerPoint"]}}})})(window.KKR);
